insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata)
values
('social-studies','b1-population-profile','b1-development-resources','1–3. Population, Statistics, Distribution and Density','Build a population profile, use official statistics for planning, and explain why people are distributed unevenly across Caribbean territories.',10,true,'{"syllabus":{"section":"B","part":"i","objectives":["1","2a","2b","3a","3b"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Describe a population using demographic and socio-economic characteristics.","Identify sources and uses of population statistics.","Explain why particular statistics matter for development planning.","Explain physical and human factors affecting population distribution and density.","Interpret choropleth and dot maps using correct map-reading conventions."],"introduction":"Population is not just the number of people in a country. Planners need to know who the people are, where they live, their age structure, employment, education, health and other characteristics. These patterns affect schools, hospitals, roads, housing and jobs.","sections":[{"title":"Building a population profile","bullets":["Age and sex structure.","Occupation, employment status and income level.","Ethnicity and religion.","Life expectancy and mortality.","Birth rate and population size.","Population density and spatial distribution.","Education and health.","Dependency ratio: the relationship between dependants and the working-age population."]},{"title":"Where statistics come from","paragraphs":["Important sources include national censuses, government statistical offices, registries of births, deaths and marriages, immigration and customs records, and records held by some institutions. A source should be checked for date, definition and coverage before figures are compared.","A census aims to collect detailed information about a population at a particular time. Administrative records are collected continuously for specific purposes. The two sources are useful in different ways."]},{"title":"Why planners need population statistics","paragraphs":["If a parish has a rapidly growing school-age population, planners may need additional classrooms and teachers. If a community has a large elderly population, health and social-care needs may be different. Statistics help governments and organisations decide where resources are most needed and evaluate whether services are reaching people."]},{"title":"Population distribution and density","paragraphs":["Distribution describes where people are located. Density expresses the number of people in relation to land area. A densely populated urban area and a sparsely populated mountain district can exist in the same country.","Physical factors include relief, climate, soils, water, fertile land and mineral resources. Human factors include employment, industry, agriculture, roads, electricity, transport and access to services."]},{"title":"Reading population maps","paragraphs":["A choropleth map shades areas according to a value or range. A dot map uses dots to represent a stated quantity or occurrence. Always read the title, key, scale and orientation before interpreting the pattern. Darker shading does not automatically mean ''better'' or ''worse''; it means whatever the key says it means."]}],"keyPoints":["Population characteristics describe composition as well as size.","Population statistics guide planning and resource allocation.","Distribution means where people live; density relates population to area.","Relief, resources, employment, infrastructure and services influence settlement patterns.","Map conclusions must follow the legend and data shown."],"summary":"Start every data question by identifying the population, place, date, unit and source. Then describe the pattern before trying to explain it.","flashcards":[{"front":"What is population density?","back":"The number of people living in a given unit of land area."},{"front":"What is population distribution?","back":"The spatial pattern showing where people live within an area."},{"front":"What is a census?","back":"A large official count and description of a population at a particular time."},{"front":"What does a choropleth map use?","back":"Shading or colour ranges to represent values for geographic areas."},{"front":"Give one human factor affecting population distribution.","back":"Examples: jobs, roads, electricity, industry, agriculture or social services."},{"front":"Why are population statistics useful?","back":"They support planning for services, infrastructure, employment and resource use."}],"interactiveModels":[{"id":"b1-population-map-reasoning","type":"social-studies","mode":"choice","title":"Population Pattern Reasoning","items":[{"context":"A coastal town has a port, highway, hospital and several large employers. The mountainous interior has few roads.","prompt":"Which explanation best accounts for a denser coastal population?","choices":["Coastal areas are always dense","Employment, transport and services attract settlement","Mountains cannot be inhabited","Population density depends only on climate"],"correctIndex":1,"explanation":"Several human factors make the coastal location more accessible and economically attractive."},{"context":"A choropleth key says darkest shade = 500+ persons per km².","prompt":"A dark parish should be described as:","choices":["The richest parish","The most developed parish","A parish in the highest density category","A parish with the largest land area"],"correctIndex":2,"explanation":"The legend supports a density statement only."}]}]}}'::jsonb),
('social-studies','b1-population-change-data','b1-development-resources','4–5. Population Change, Demographic Rates and Data Skills','Explain population change, calculate demographic rates, choose statistical diagrams and combine evidence from multiple sources.',20,true,'{"syllabus":{"section":"B","part":"i","objectives":["4a","4b","4c","4d","5"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Explain how births, deaths and migration change population.","Calculate birth rate, death rate, natural increase, population growth and net migration.","Choose suitable graphs, charts or population pyramids for different data.","Represent demographic data accurately.","Integrate information from multiple reliable sources to reach a conclusion."],"introduction":"Population changes because people are born, die, immigrate and emigrate. Demographic rates make comparisons fairer by relating events to population size. CXC also expects you to choose and interpret suitable statistical diagrams.","sections":[{"title":"The population-change equation","paragraphs":["Natural increase is the difference between births and deaths. Migration changes population when people enter or leave. Net migration equals immigration minus emigration. Overall population growth combines natural increase and net migration.","A negative net migration figure means more people left than entered during the period. It does not by itself explain why they left."]},{"title":"Common demographic rates","bullets":["Crude birth rate = (live births ÷ total population) × 1,000.","Crude death rate = (deaths ÷ total population) × 1,000.","Rate of natural increase can be obtained from the difference between birth and death rates when they use the same base.","Net migration = immigration − emigration.","Overall population change = births − deaths + immigration − emigration."]},{"title":"Choosing the right diagram","bullets":["Line graph: useful for change through time.","Bar graph: useful for comparing discrete categories.","Pie chart: useful for showing how a total is divided into percentage parts.","Population pyramid: useful for displaying age-sex structure."]},{"title":"Integrating sources","paragraphs":["One source may show census population, another migration flows, and a third employment trends. Integration means examining the sources together, checking reliability and using them to support one informed conclusion. It is not simply placing three quotations in the same paragraph."]}],"keyPoints":["Births and immigration add to population; deaths and emigration reduce it.","Rates allow more meaningful comparisons than raw counts when populations differ.","The graph type should match the structure of the data.","Multiple sources strengthen a conclusion only when they are relevant and reliable."],"summary":"Show working in demographic calculations. In data questions, label units clearly and distinguish a rate per 1,000 from a percentage.","flashcards":[{"front":"How is crude birth rate calculated?","back":"Live births ÷ total population × 1,000."},{"front":"How is crude death rate calculated?","back":"Deaths ÷ total population × 1,000."},{"front":"What is net migration?","back":"Immigration minus emigration."},{"front":"Which graph suits change over time?","back":"A line graph is usually appropriate for time-series data."},{"front":"Which diagram shows age-sex structure?","back":"A population pyramid."},{"front":"What does integrating sources mean?","back":"Combining reliable evidence from several sources to support one reasoned conclusion."}],"interactiveModels":[{"id":"b1-demographic-calculator","type":"social-studies","mode":"calculator","title":"Demographic Rate Lab","items":[{"prompt":"A territory has 18,000 live births and a population of 1,200,000. Calculate the crude birth rate.","data":[["Live births","18,000"],["Population","1,200,000"]],"formula":"(births ÷ population) × 1,000","answer":15,"unit":"per 1,000","explanation":"18,000 ÷ 1,200,000 × 1,000 = 15 per 1,000."},{"prompt":"A country records 24,500 immigrants and 31,000 emigrants. Calculate net migration.","data":[["Immigrants","24,500"],["Emigrants","31,000"]],"formula":"immigration − emigration","answer":-6500,"unit":"people","explanation":"24,500 − 31,000 = −6,500, so more people left than entered."},{"prompt":"Birth rate is 17 per 1,000 and death rate is 8 per 1,000. Find the rate of natural increase.","data":[["Birth rate","17 per 1,000"],["Death rate","8 per 1,000"]],"formula":"birth rate − death rate","answer":9,"unit":"per 1,000","explanation":"17 − 8 = 9 per 1,000."}]}]}}'::jsonb),
('social-studies','b1-migration-diaspora','b1-development-resources','6–7. Migration, the Caribbean Diaspora and Global Impact','Analyse push and pull factors, consequences of migration and the contribution of Caribbean migrants to host societies and the region.',30,true,'{"syllabus":{"section":"B","part":"i","objectives":["6a","6b","7"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Explain push and pull factors influencing migration.","Distinguish internal, intra-regional, external, forced and seasonal migration.","Examine effects on migrants, countries of origin and host countries.","Explain historical and contemporary reasons for Caribbean migration.","Assess economic, cultural and social impacts of the Caribbean diaspora."],"introduction":"Migration is the movement of people from one place to another to live or work for a period of time. Caribbean migration has connected the region to Panama, North America, the United Kingdom and many other places. Its effects can be positive, negative or mixed depending on whose experience is being examined.","sections":[{"title":"Types of migration","bullets":["Internal migration: movement within the same country, such as rural to urban movement.","Intra-regional migration: movement between Caribbean countries.","External migration: movement from the Caribbean to another world region.","Forced or involuntary migration: movement where people have little meaningful choice because of danger, persecution or other compelling circumstances.","Seasonal migration: temporary movement linked to a recurring period of work or activity."]},{"title":"Push and pull factors","paragraphs":["Push factors encourage people to leave a place, while pull factors attract them to another. Employment, wages, education, health care, family ties, government policy, conflict, population pressure and natural disasters can operate as push or pull factors depending on the situation."]},{"title":"Effects on the country of origin","bullets":["Remittances can support households and bring foreign exchange.","Brain drain can reduce the supply of scarce skilled workers.","Emigration may reduce population pressure or contribute to depopulation in some places.","Diaspora networks can support investment, tourism, culture and advocacy."]},{"title":"Effects on the host country and migrant","bullets":["Migrants may add skills, labour, entrepreneurship, taxes and cultural diversity.","Migrants may gain education, employment or safety.","Host communities may experience pressure on services where planning does not match rapid population change.","Migrants can face discrimination, exploitation, underemployment or difficulty adapting."]},{"title":"Historical Caribbean destinations","paragraphs":["The syllabus highlights migration to destinations such as Panama, the United Kingdom, the United States and Canada. Reasons have included employment, education, disaster, medical care and asylum. The specific historical period matters when explaining why a destination attracted Caribbean migrants."]}],"keyPoints":["Push factors encourage departure; pull factors attract migrants.","Migration effects differ for the migrant, origin country and host country.","Brain drain is the loss of skilled human resources through emigration.","Remittances are transfers of money or resources sent by migrants to people in another country.","Diaspora communities can spread Caribbean culture and support regional interests abroad."],"summary":"Do not call migration simply ''good'' or ''bad''. Identify who is affected, then explain a specific benefit, cost or trade-off.","flashcards":[{"front":"What is a push factor?","back":"A condition that encourages a person to leave a place."},{"front":"What is a pull factor?","back":"A condition that attracts a person to a destination."},{"front":"What is brain drain?","back":"Loss of skilled human resources when trained people emigrate."},{"front":"What are remittances?","back":"Money or resources migrants send to people, often relatives, in another country."},{"front":"What is intra-regional migration?","back":"Movement between countries within the same region."},{"front":"Give one possible host-country benefit of migration.","back":"Examples include added skills, labour, entrepreneurship, taxes or cultural diversity."}],"interactiveModels":[{"id":"b1-migration-sort","type":"social-studies","mode":"classify","title":"Push, Pull or Consequence?","categories":["Push factor","Pull factor","Consequence"],"items":[{"label":"A major hurricane destroys homes and jobs.","category":"Push factor"},{"label":"A university offers a specialised scholarship abroad.","category":"Pull factor"},{"label":"A hospital loses several experienced nurses to emigration.","category":"Consequence"},{"label":"A migrant sends part of her wages home each month.","category":"Consequence"},{"label":"A seasonal farm programme offers temporary paid work.","category":"Pull factor"}]}]}}'::jsonb),
('social-studies','b1-human-resources','b1-development-resources','8–9. Developing Human Resources','Explain why Caribbean development depends on healthy, educated, skilled, adaptable people and the institutions that support them.',40,true,'{"syllabus":{"section":"B","part":"i","objectives":["8","9"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Explain why productive, creative and critical-thinking workers matter to development.","Explain how nutrition, health care, education, training, finance, sports and culture develop human resources.","Assess the importance of access as well as availability.","Explain how technology changes access to education and training."],"introduction":"A country''s human resources are the knowledge, skills, health, creativity and productive capacity of its people. Natural resources can create opportunities, but people need the ability to manage, improve and use those resources wisely.","sections":[{"title":"Why human resources matter","paragraphs":["Productive workers create goods and services. Skilled workers can use technology, solve problems and adapt to change. Creative and critical thinkers can identify new opportunities instead of only repeating existing methods.","Human-resource development also supports citizenship, health, community leadership and quality of life. It is wider than training people for jobs."]},{"title":"What develops people","bullets":["Nutrition and preventive health support physical and cognitive development.","Accessible primary and curative health care helps people remain healthy and productive.","Basic, technical, vocational and professional education develop knowledge and occupational skills.","Retraining and lifelong learning help workers adjust when industries or technologies change.","Scholarships and financial support can widen access.","Sports and culture build talents, discipline, identity and economic opportunities.","Technology can expand access through online learning and digital resources, although unequal connectivity can create new barriers."]},{"title":"Availability is not the same as access","paragraphs":["A training institution may exist but remain inaccessible because of cost, distance, disability barriers, entry requirements or lack of internet access. Strong answers separate the existence of a resource from people''s real ability to use it."]},{"title":"Caribbean example","paragraphs":["If a community college launches a renewable-energy technician programme, the benefit depends on more than the syllabus. Students may need transport, equipment, qualified instructors, work placements and financial support. Human-resource development is a system."]}],"keyPoints":["Human-resource development builds health, knowledge, skills and productive capacity.","Education, health, finance, sports, culture and technology all contribute.","Access determines whether opportunities can actually be used.","Retraining and lifelong learning are important when economies and technologies change."],"summary":"When explaining a factor, show the pathway from investment in people to an outcome such as productivity, employability, innovation or quality of life.","flashcards":[{"front":"What are human resources?","back":"The knowledge, skills, health and productive capabilities of people."},{"front":"Why is lifelong learning important?","back":"It helps people adapt as jobs, technologies and economic needs change."},{"front":"How does health support human-resource development?","back":"Healthy people can learn, work and participate more effectively."},{"front":"Why distinguish availability from access?","back":"A service can exist while cost, distance or other barriers prevent people from using it."},{"front":"How can technology help human-resource development?","back":"It can widen access to learning, information, training and collaboration."}],"interactiveModels":[{"id":"b1-human-resource-chain","type":"social-studies","mode":"choice","title":"From Investment to Development","items":[{"context":"A rural training centre offers online technical courses, but many students have no reliable internet.","prompt":"What is the main issue?","choices":["No education is available","Availability exists but access is limited","Technology never helps education","Students do not value training"],"correctIndex":1,"explanation":"The programme exists, but connectivity affects real access."},{"context":"A country funds retraining for workers displaced by automation.","prompt":"What is the most direct purpose?","choices":["Reduce all migration","Help workers adapt to changing skill demands","Eliminate technology","Replace health care"],"correctIndex":1,"explanation":"Retraining helps human resources adjust to new employment requirements."}]}]}}'::jsonb),
('social-studies','b1-employment-industries','b1-development-resources','10–11. Employment, Unemployment and Careers Across Industries','Explain labour-market conditions and connect Caribbean career opportunities to primary, secondary, tertiary and quaternary industries.',50,true,'{"syllabus":{"section":"B","part":"i","objectives":["10","11"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Explain factors affecting employment, unemployment and underemployment.","Distinguish employment, unemployment and underemployment.","Classify primary, secondary, tertiary and quaternary industries.","Identify career opportunities and transferable skills across sectors."],"introduction":"Having people who want to work does not automatically create jobs. Employment depends on investment, skills, markets, technology, economic conditions and entrepreneurship. The type of work available also changes as economies develop.","sections":[{"title":"Key labour-market ideas","bullets":["Employment: engaging in paid or income-generating work under the definition used for the data source.","Unemployment: being without work while meeting the source''s criteria for being available for and seeking work.","Underemployment: working less than desired or in work that does not fully use available time or skills, depending on the measure used.","Labour-force definitions can vary slightly by statistical agency, so use the definition given in a question or source."]},{"title":"Factors influencing employment","bullets":["Availability and productive use of capital.","Supply of trained workers and match between skills demanded and skills available.","Market size, trade patterns and consumer demand.","Technology and the methods firms use to produce goods and services.","Economic downturn or recession.","Gender barriers or unequal opportunities.","Entrepreneurship and the ability to create new businesses and markets."]},{"title":"Four industry groups","bullets":["Primary: extracting or harvesting natural resources, such as agriculture, fishing and mining.","Secondary: processing materials or building products, such as manufacturing and construction.","Tertiary: services, including tourism, transport, finance and many professional services.","Quaternary: knowledge-intensive activity such as information technology, data, research and development."]},{"title":"Careers connect across sectors","paragraphs":["A hotel belongs to the tertiary sector, but it buys food from agriculture, furniture from manufacturing and software from technology providers. This creates linkages. A career such as accounting, marketing or IT can also serve firms in several industries."]}],"keyPoints":["Unemployment and underemployment are different labour-market conditions.","Employment depends on skills, investment, markets, technology and wider economic conditions.","Primary, secondary, tertiary and quaternary sectors describe different forms of economic activity.","Industries are linked rather than isolated."],"summary":"For employment questions, explain the mechanism. For example, do not just write ''technology affects jobs''; explain whether it creates new skills demand, improves productivity or replaces particular tasks.","flashcards":[{"front":"What is underemployment?","back":"Work that does not fully use a person''s available time or skills, depending on the measure."},{"front":"What is a primary industry?","back":"An industry that extracts or harvests natural resources, such as farming, fishing or mining."},{"front":"What is a secondary industry?","back":"An industry that processes materials or constructs products and infrastructure."},{"front":"What is a tertiary industry?","back":"A service industry such as tourism, finance, transport or retail."},{"front":"What is a quaternary industry?","back":"Knowledge-intensive activity such as IT, research, data or development work."},{"front":"How can a skills mismatch cause unemployment?","back":"Available workers may not have the skills employers need for existing vacancies."}],"interactiveModels":[{"id":"b1-industry-sort","type":"social-studies","mode":"classify","title":"Which Industry?","categories":["Primary","Secondary","Tertiary","Quaternary"],"items":[{"label":"A fisher harvests lobster for sale.","category":"Primary"},{"label":"A factory turns fruit into bottled juice.","category":"Secondary"},{"label":"A hotel provides accommodation and guest services.","category":"Tertiary"},{"label":"A software team develops a data platform for exporters.","category":"Quaternary"},{"label":"A construction company builds a new health centre.","category":"Secondary"}]}]}}'::jsonb),
('social-studies','b1-natural-resources','b1-development-resources','12. Caribbean Natural Resources and Their Uses','Identify renewable and non-renewable resource bases and connect resources to livelihoods, energy, tourism and sustainable development.',60,true,'{"syllabus":{"section":"B","part":"i","objectives":["12a","12b"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Identify major renewable and non-renewable natural resources found in the Caribbean.","Describe major uses of agricultural land, water, forests, marine resources and minerals.","Explain how solar, wind, geothermal, hydro and bioenergy relate to sustainable development.","Recognise that resource locations differ across territories."],"introduction":"The Caribbean is often described through beaches and climate, but the region''s resource base is much broader. Land, forests, water, marine ecosystems, minerals and renewable-energy potential support food, jobs, exports, settlement and tourism.","sections":[{"title":"Renewable resources","bullets":["Agricultural land can produce food and export crops if soils are managed carefully.","Fresh water supports households, agriculture, industry and ecosystems.","Forests provide timber and non-timber products, protect watersheds and store carbon.","Marine and terrestrial life support fisheries, tourism and biodiversity.","Solar, wind, geothermal, hydro and bioenergy can be replenished or continuously available when managed within natural limits."]},{"title":"Non-renewable resources","paragraphs":["Resources such as petroleum, bauxite, gold, diamonds and other minerals form over geological time and are depleted when extracted. Their economic value can be significant, but extraction can also create environmental costs that require management."]},{"title":"Resource use involves choices","paragraphs":["The same coastal area may be valued for fishing, mangrove protection, housing and tourism. The same forest may provide timber, biodiversity, water protection and recreation. Sustainable planning weighs competing uses instead of treating a resource as if it has only one value."]},{"title":"Energy transition","paragraphs":["Renewable energy can reduce dependence on imported fossil fuels and lower greenhouse-gas emissions, but projects still require land, finance, grids, maintenance and community planning. ''Renewable'' does not mean ''impact-free''."]}],"keyPoints":["Renewable resources can regenerate or remain available if use stays within sustainable limits.","Non-renewable resources are finite on human timescales.","Resources have economic, social and ecological uses.","Sustainable development balances present needs with the ability of future generations to meet theirs."],"summary":"Learn examples, but always connect the resource to a use and a possible management issue.","flashcards":[{"front":"Give three renewable Caribbean resources.","back":"Examples: solar energy, wind, forests, water, agricultural land or marine life."},{"front":"Give three non-renewable Caribbean resources.","back":"Examples: petroleum, bauxite, gold, diamonds or other minerals."},{"front":"Why are forests more than a timber resource?","back":"They also support biodiversity, watersheds, carbon storage, tourism and livelihoods."},{"front":"What is sustainable resource use?","back":"Using resources to meet present needs without undermining future availability and environmental health."},{"front":"Why is renewable energy not impact-free?","back":"Projects still use land, materials, infrastructure and can affect communities and ecosystems."}],"interactiveModels":[{"id":"b1-resource-sort","type":"social-studies","mode":"classify","title":"Renewable or Non-renewable?","categories":["Renewable","Non-renewable"],"items":[{"label":"Solar energy","category":"Renewable"},{"label":"Bauxite","category":"Non-renewable"},{"label":"Geothermal energy","category":"Renewable"},{"label":"Petroleum","category":"Non-renewable"},{"label":"A sustainably managed forest","category":"Renewable"},{"label":"Gold deposits","category":"Non-renewable"}]}]}}'::jsonb),
('social-studies','b1-sustainable-practices','b1-development-resources','13. Sustainable and Unsustainable Environmental Practices','Examine how land use, agriculture, tourism, pollution and conservation practices affect the environment and population.',70,true,'{"syllabus":{"section":"B","part":"i","objectives":["13"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Distinguish sustainable from unsustainable environmental practices.","Explain how farming and land-use practices can reduce or increase erosion.","Examine environmental effects of resort development, land reclamation and waste disposal.","Explain how conservation can support food security, ecosystems and long-term livelihoods."],"introduction":"Sustainability is easiest to understand by asking what happens after repeated use. A practice is not sustainable merely because it earns income today. It should protect the environmental systems and resource base on which future well-being depends.","sections":[{"title":"Examples of sustainable practice","bullets":["Reforestation and controlled logging.","Contour ploughing and terracing on slopes.","Crop rotation and soil conservation.","Zoning and protected reserves.","Waste reduction and proper disposal.","Protection of reefs, mangroves, forests and heritage sites."]},{"title":"Examples of damaging practice","bullets":["Removing vegetation from steep slopes.","Repeated monocropping without adequate soil management.","Ploughing straight up and down steep slopes where this accelerates runoff.","Deforestation without restoration.","Poorly planned housing or resort development.","Sewage, industrial waste and other pollution entering rivers and coastal waters."]},{"title":"Follow the chain of effects","paragraphs":["Vegetation removal can expose soil. Heavy rain can then increase runoff and erosion. Sediment may enter rivers and reefs, affecting water quality and marine ecosystems. A strong answer explains this chain rather than simply saying ''deforestation is bad''."]},{"title":"Tourism and conservation","paragraphs":["Tourism can place pressure on coasts, water, reefs and waste systems, but it can also create incentives and revenue for conservation when carefully planned. Evaluate the design and management of the activity, not the word ''tourism'' by itself."]}],"keyPoints":["Sustainable practice protects the resource base while meeting human needs.","Environmental effects often occur through linked cause-and-effect chains.","Soil conservation, zoning, protected areas and restoration are management tools.","Development and conservation can create trade-offs that require evidence-based decisions."],"summary":"For environmental questions, use a chain: practice → environmental change → effect on people/resources → management response.","flashcards":[{"front":"How does contour ploughing reduce erosion?","back":"Ploughing across a slope slows runoff and reduces soil loss."},{"front":"Why can deforestation increase flooding?","back":"Less vegetation intercepts rain and stabilises soil, so runoff can increase."},{"front":"What is zoning?","back":"Planning rules that control where particular land uses or developments may occur."},{"front":"How can pollution affect coral reefs?","back":"Poor water quality and excess sediments or nutrients can damage reef ecosystems."},{"front":"How can tourism support conservation?","back":"Well-managed tourism can fund protection and create value for natural and heritage assets."}],"interactiveModels":[{"id":"b1-sustainability-sort","type":"social-studies","mode":"classify","title":"Sustainable Practice Check","categories":["More sustainable","Less sustainable"],"items":[{"label":"Replanting trees after controlled timber harvesting","category":"More sustainable"},{"label":"Clearing mangroves without assessing flood and habitat effects","category":"Less sustainable"},{"label":"Terracing a steep cultivated hillside","category":"More sustainable"},{"label":"Discharging untreated sewage into a bay","category":"Less sustainable"},{"label":"Using zoning to keep major construction away from a vulnerable wetland","category":"More sustainable"}]}]}}'::jsonb),
('social-studies','b1-climate-data-environment','b1-development-resources','14–19. Climate Change, Resource Data, Environmental Care and Caribbean Location','Explain climate change, evaluate responses, interpret resource data and locate the Caribbean in the wider world.',80,true,'{"syllabus":{"section":"B","part":"i","objectives":["14","15","16","17","18","19"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Explain natural and human causes of climate change and major consequences for the Caribbean.","Evaluate individual, government, regional and international responses.","Represent and interpret physical-resource data in tables, graphs and charts.","Demonstrate practical care for the natural environment.","Locate the Caribbean region in relation to surrounding landmasses and bodies of water."],"introduction":"Small island and coastal Caribbean societies are highly exposed to climate and environmental change. This topic connects global processes to local consequences: stronger coastal risk, water stress, agriculture, fishing, tourism, health and infrastructure.","sections":[{"title":"Global warming and climate change","paragraphs":["Global warming refers to the long-term rise in Earth''s average surface temperature, driven in the modern period mainly by increased greenhouse gases from human activities. Climate change includes warming and broader long-term shifts in climate patterns. Natural factors can affect climate too, but current planning must account for human-driven warming and its consequences."]},{"title":"Caribbean consequences","bullets":["Sea-level rise and increased coastal flooding risk.","More damaging effects from extreme rainfall, drought and intense tropical cyclones.","Stress on coral reefs and marine resources.","Changing conditions for agriculture, forestry and fisheries.","Pressure on water supply.","Health risks associated with heat, disease patterns and disaster impacts.","Tourism losses where beaches, reefs, infrastructure or heritage sites are damaged."]},{"title":"Responses","paragraphs":["Mitigation reduces the causes of climate change, for example by lowering greenhouse-gas emissions and increasing clean energy. Adaptation reduces vulnerability to effects that are occurring or expected, for example stronger building codes, coastal planning, water conservation and disaster preparedness.","Individuals and communities can reduce waste, reuse and recycle, use efficient transport and energy, and support local conservation. Governments use planning, regulation, infrastructure, education and enforcement. Regional and international cooperation supports finance, science and coordinated policy."]},{"title":"Representing and interpreting resource data","paragraphs":["Use bar graphs for categories, line graphs for change over time and pie charts for parts of a total. Titles, units, labels and scales must be clear. When interpreting, state the pattern with evidence before suggesting a reason."]},{"title":"Environmental citizenship","paragraphs":["Care for the environment includes recycling, conservation, responsible consumption, advocacy, volunteering and collective action. Effective environmental citizenship connects behaviour to a real environmental outcome rather than treating a slogan as action."]},{"title":"Where is the Caribbean?","paragraphs":["The Caribbean lies southeast of the Gulf of Mexico and North America, east of Central America and north of South America, around the Caribbean Sea and adjacent Atlantic Ocean. The region includes island territories and mainland states with strong Caribbean historical and institutional ties such as Belize, Guyana and Suriname."]}],"keyPoints":["Mitigation addresses causes; adaptation reduces vulnerability to impacts.","Climate effects interact with tourism, agriculture, water, health and infrastructure.","Graphs must use suitable forms, scales, labels and units.","Environmental responsibility includes individual and collective action.","The Caribbean is a region of islands and mainland territories connected geographically, historically and institutionally."],"summary":"Separate cause, consequence and response. In climate questions, distinguish mitigation from adaptation and use Caribbean-specific examples.","flashcards":[{"front":"What is climate-change mitigation?","back":"Action that reduces greenhouse-gas emissions or increases removal of greenhouse gases."},{"front":"What is climate adaptation?","back":"Action that reduces vulnerability to present or expected climate impacts."},{"front":"Give one Caribbean climate risk.","back":"Examples: sea-level rise, coastal flooding, drought, intense hurricanes or coral-reef damage."},{"front":"Which graph best shows a resource changing yearly?","back":"A line graph is usually appropriate for time-series data."},{"front":"Name two forms of environmental citizenship.","back":"Examples: conservation, recycling, advocacy, volunteering or responsible consumption."},{"front":"Where is the Caribbean relative to South America?","back":"Mainly north of South America around the Caribbean Sea and adjacent Atlantic."}],"interactiveModels":[{"id":"b1-climate-response","type":"social-studies","mode":"classify","title":"Mitigation or Adaptation?","categories":["Mitigation","Adaptation"],"items":[{"label":"Replacing diesel electricity with solar generation","category":"Mitigation"},{"label":"Updating coastal building standards for stronger storm surge","category":"Adaptation"},{"label":"Improving drought-resistant water storage systems","category":"Adaptation"},{"label":"Reducing fossil-fuel use in transport","category":"Mitigation"},{"label":"Restoring mangroves to reduce coastal-wave impacts","category":"Adaptation"}]}],"visualSources":[{"id":"caribbean-map","title":"Blank Map of the Caribbean","creator":"NuclearVacuum","source":"Wikimedia Commons","license":"Public domain","assetUrl":"https://upload.wikimedia.org/wikipedia/commons/7/71/BlankMap-Caribbean.svg","url":"https://commons.wikimedia.org/wiki/File:BlankMap-Caribbean.svg","alt":"Blank political map of the Caribbean region","purpose":"Caribbean location and map-skills practice"}]}}'::jsonb)
