begin;
on conflict(subject_id,topic_id) do update set section_id=excluded.section_id,title=excluded.title,description=excluded.description,sort_order=excluded.sort_order,enabled=excluded.enabled,metadata=excluded.metadata,updated_at=now();

on conflict(subject_id,activity_key) do update set activity_type=excluded.activity_type,section_id=excluded.section_id,topic_id=excluded.topic_id,title=excluded.title,route=excluded.route,evidence_weight=excluded.evidence_weight,enabled=excluded.enabled,metadata=excluded.metadata,updated_at=now();
commit;
